62	    {
63	        get{return _level;}
64	        protected set
65	        {
66	            _level = value;
67	            OnPropertyChanged();
68	        }
69	    }
70	    public Inventory Inventory
71	    {
72	        get => _inventory;
73	        private set
74	        {
75	            _inventory = value;
76	            OnPropertyChanged();
77	        }
78	    }
79	
80	    public GameItem? CurrentWeapon
81	    {
82	        get{return _currentWeapon;}
83	        set
84	        {
85	            if(_currentWeapon?.Action != null)
86	            {
87	                _currentWeapon.Action.OnActionPerformed -= RaiseActionPerformedEvent;
88	            }
89	            _currentWeapon = value;
90	            if(_currentWeapon?.Action != null)
91	            {
92	                _currentWeapon.Action.OnActionPerformed += RaiseActionPerformedEvent;
93	            }
94	            OnPropertyChanged();
95	        }
96	    }
97	
98	    public GameItem? CurrentConsumable
99	    {
100	        get{return _currentConsumable;}
101	        set
102	        {
103	            if(_currentConsumable?.Action != null)
104	            {
105	                _currentConsumable.Action.OnActionPerformed -= RaiseActionPerformedEvent;
106	            }
107	            _currentConsumable = value;
108	            if(_currentConsumable?.Action != null)
109	            {
110	                _currentConsumable.Action.OnActionPerformed += RaiseActionPerformedEvent;
111	            }
112	            OnPropertyChanged();
113	        }
114	    }
115	    [JsonIgnore]
116	    public bool IsAlive => CurrentHitPoints > 0;
117	    [JsonIgnore]
118	    public bool IsDead => !IsAlive;
119	    public event EventHandler<string>? OnActionPerformed;
120	    public event EventHandler? OnKilled;
121	
122	    protected LivingEntity(string name, int maximumHitPoints, int currentHitPoints,
123	                            IEnumerable<PlayerAttribute> attributes, int gold, int level = 1)
124	    {
125	        Name = name;
126	        MaximumHitPoints = maximumHitPoints;
127	        CurrentHitPoints = currentHitPoints;
128	        Gold = gold;
129	        Level = level;
130	        foreach(PlayerAttribute attribute in attributes){
131	            Attributes.Add(attribute);
132	        }
133	
134	        Inventory = new Inventory();
135	    }
136	
137	    public void UseCurrentWeaponOn(LivingEntity target)
138	    {
139	        if(CurrentWeapon == null)
140	        {
141	            return;
142	        }
143	        CurrentWeapon.PerformAction(this, target);
144	    }
145	
146	    public void UseCurrentConsumable()
147	    {
148	        GameItem? consumable = CurrentConsumable;
149	        if(consumable == null)
150	        {
151	            return;
152	        }
153	        consumable.PerformAction(this, this);
154	        RemoveItemFromInventory(consumable);
155	    }
156	
157	    public void TakeDamage(int value)
158	    {
159	        CurrentHitPoints -= value;
160	        if (IsDead)
161	        {
162	            CurrentHitPoints = 0;
163	            RaiseOnKilledEvent();
164	        }
165	    }
166	
167	    public void Heal(int value)
168	    {
169	        CurrentHitPoints += value;
170	        if(CurrentHitPoints > MaximumHitPoints)
171	        {
172	            CurrentHitPoints = MaximumHitPoints;
173	        }
174	    }
175	
176	    public void CompleteHeal()
177	    {
178	        CurrentHitPoints = MaximumHitPoints;
179	    }
180	
181	    public void ReceiveGold(int value)
182	    {
183	        Gold += value;
184	    }
185	
186	    public void SpendGold(int value)
187	    {
188	        if(value > Gold)
189	        {
190	            throw new ArgumentOutOfRangeException($"{Name} only has {Gold} gold");
191	        }
192	        Gold -= value;
193	    }
194	
195	    public void AddItemToInventory(GameItem item)
196	    {   
197	        Inventory = Inventory.AddItem(item);
198	    }
199	
200	    public void RemoveItemFromInventory(GameItem item)
201	    {
202	        ReplaceInventoryAfterRemoval(Inventory.RemoveItem(item));
203	    }
204	
205	    public void RemoveItemsFromInventory(List<ItemQuantity> itemQuantities)
206	    {
207	        ReplaceInventoryAfterRemoval(Inventory.RemoveItems(itemQuantities));
208	    }
209	
210	    // Unequip anything that just left the inventory. Only items that were in the old
211	    // inventory count: a monster's weapon is never in its inventory and must stay equipped.
212	    private void ReplaceInventoryAfterRemoval(Inventory newInventory)
213	    {
214	        Inventory oldInventory = Inventory;
215	        Inventory = newInventory;
216	
217	        if(WasRemoved(CurrentWeapon))
218	        {
219	            CurrentWeapon = null;
220	        }
221	        if(WasRemoved(CurrentConsumable))
222	        {
223	            CurrentConsumable = null;
224	        }
225	
226	        bool WasRemoved(GameItem? item) =>
227	            item != null && oldInventory.Items.Contains(item) && !newInventory.Items.Contains(item);
228	    }
229	    private void RaiseOnKilledEvent()
230	    {
231	        OnKilled?.Invoke(this, new System.EventArgs());
232	    }
233	
234	    private void RaiseActionPerformedEvent(object? sender,string result)
235	    {
236	        OnActionPerformed?.Invoke(this, result);
237	    }
238	}

