    30	    public void AddMonster(int monsterID, int chanceOfEncountering)
    31	    {
    32	        if (MonstersHere.Exists(m => m.MonsterID == monsterID))
    33	        {
    34	            MonstersHere.First(m => m.MonsterID == monsterID).ChanceOfEncountering = chanceOfEncountering;
    35	        }
    36	        else
    37	        {
    38	            MonstersHere.Add(new MonsterEncounter(monsterID, chanceOfEncountering));
    39	        }
    40	    }
