    42	    public Monster? GetMonster()
    43	    {
    44	        if (!MonstersHere.Any())
    45	        {
    46	            return null;
    47	        }
    48	
    49	        int totalChances = MonstersHere.Sum(m => m.ChanceOfEncountering);
    50	
    51	        int randomNumber = DiceService.Instance.Roll(totalChances).Value;
    52	
    53	        int runningTotal = 0;
    54	
    55	        foreach (MonsterEncounter monsterEncounter in MonstersHere)
    56	        {
    57	            runningTotal += monsterEncounter.ChanceOfEncountering;
    58	
    59	            if (randomNumber <= runningTotal)
    60	            {
    61	                return MonsterFactory.GetMonster(monsterEncounter.MonsterID);
    62	            }
    63	        }
    64	
    65	        // If there was a problem, return the last monster in the list.
    66	        return MonsterFactory.GetMonster(MonstersHere.Last().MonsterID);
    67	    }
    68	}
