     7	namespace Engine.Factories;
     8	public static class MonsterFactory
     9	{      
    10	    // Resolved against the folder holding the .exe, not the current working directory,
    11	    // so the game and the tests find the data file wherever they are launched from.
    12	    private static readonly string GAME_DATA_FILENAME =
    13	        Path.Combine(AppContext.BaseDirectory, "GameData", "Monsters.xml");
    14	    private static readonly GameDetails s_gameDetails;
    15	    private static readonly List<Monster> _baseMonsters = new List<Monster>();
    16	    static MonsterFactory()
    17	    {
    18	        if (File.Exists(GAME_DATA_FILENAME))
    19	        {   
    20	            s_gameDetails = GameDetailService.ReadGameDetails();
    21	            XmlDocument data = new XmlDocument();
    22	            data.LoadXml(File.ReadAllText(GAME_DATA_FILENAME));
    23	            string rootImagePath = 
    24	                    data.SelectSingleNode("/Monsters").AttributeAsString("RootImagePath");
    25	            LoadMonstersFromNodes(data.SelectNodes("/Monsters/Monster"), rootImagePath);
    26	        }
    27	        else
    28	        {
    29	            throw new FileNotFoundException($"Missing data file: {GAME_DATA_FILENAME}");
    30	        }
    31	    }
    32	    private static void LoadMonstersFromNodes(XmlNodeList nodes, string rootImagePath)
    33	    {
    34	        if(nodes == null)
    35	        {
    36	            return;
    37	        }
    38	        foreach(XmlNode node in nodes)
    39	        {   
    40	            var attributes = s_gameDetails.PlayerAttributes;
    41	            attributes.First(a => a.Key.Equals("DEX")).BaseValue = Convert.ToInt32(node.SelectSingleNode("./Dexterity").InnerText);
    42	            attributes.First(a => a.Key.Equals("DEX")).ModifiedValue = Convert.ToInt32(node.SelectSingleNode("./Dexterity").InnerText);
    43	
    44	            Monster monster = new Monster(
    45	                node.AttributeAsInt("ID"),
    46	                node.AttributeAsString("Name"),
    47	                $".{rootImagePath}{node.AttributeAsString("ImageName")}",
    48	                node.AttributeAsInt("MaximumHitPoints"),
    49	                attributes,
    50	                ItemFactory.CreateGameItem(node.AttributeAsInt("WeaponID")),
    51	                node.AttributeAsInt("RewardXP"),
    52	                node.AttributeAsInt("Gold")
    53	            );
    54	            XmlNodeList lootItemNodes = node.SelectNodes("./LootItems/LootItem");
    55	            if(lootItemNodes != null)
    56	            {
    57	                foreach(XmlNode lootItemNode in lootItemNodes)
    58	                {
    59	                    monster.AddItemToLootTable(lootItemNode.AttributeAsInt("ID"), lootItemNode.AttributeAsInt("Percentage"));
    60	                }
    61	            }
    62	            _baseMonsters.Add(monster);
    63	        }
    64	    }
    65	
    66	    public static Monster GetMonster(int id)
    67	    {
    68	        return _baseMonsters.FirstOrDefault(m => m.ID == id)?.GetNewInstance();
    69	    }
