namespace Engine.Models;

public class Monster : LivingEntity
{
    public int ID {get;}
    public string ImageName { get;}
    public int RewardedExperiencePoints { get; }
    public List<ItemPercentage> LootTable { get; } = new List<ItemPercentage>();

    public Monster(int id,string name, string imageName, int maximumHitPoints,IEnumerable<PlayerAttribute> attributes, GameItem currentWeapon,int rewardedExperiencePoints, int rewardedGold) :
    base(name, maximumHitPoints, maximumHitPoints, attributes, rewardedGold)
    {
        ID = id;
        ImageName = imageName;
        CurrentWeapon = currentWeapon;
        RewardedExperiencePoints = rewardedExperiencePoints;
    }

    public void AddItemToLootTable(int id, int percentage)
    {
        LootTable.RemoveAll(ip => ip.ID == id);
        LootTable.Add(new ItemPercentage(id, percentage));
    }

    public Monster Clone()
    {
        // Each spawn needs its own weapon: the Action carries the holder, so a shared
        // weapon would report one monster's attacks through every other monster of this type.
        Monster newMonster = new Monster(ID, Name, ImageName, MaximumHitPoints, Attributes, CurrentWeapon.Clone(), RewardedExperiencePoints, Gold);
        newMonster.LootTable.AddRange(LootTable);
        return newMonster;
    }
}

